import{_ as t,o as i,c as o,ag as a}from"./chunks/framework.DaCm-iTo.js";const u=JSON.parse('{"title":"CoreLib Actions","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/cooking/corelib-actions.md","filePath":"en/modules/cooking/corelib-actions.md","lastUpdated":null}'),s={name:"en/modules/cooking/corelib-actions.md"};function d(n,e,r,c,h,l){return i(),o("div",null,[...e[0]||(e[0]=[a(`<h1 id="corelib-actions" tabindex="-1">CoreLib Actions <a class="header-anchor" href="#corelib-actions" aria-label="Permalink to &quot;CoreLib Actions&quot;">​</a></h1><p>When EmakiCooking is enabled, it adds nutrition, threshold recheck, and recipe reward stages to the CoreLib action registry. They can be used by other module action lists, CoreLib pipeline templates, or pipelines triggered by third parties through the CoreLib pipeline engine.</p><blockquote><p>This page documents only the stages registered by EmakiCooking. CoreLib built-in stages are documented in <a href="./../corelib/actions.html">CoreLib Actions</a>. Current stage IDs use only the canonical names below; historical aliases are no longer registered. The old <code>emakicookingaddnutrition</code> is now written <code>cooking_add_nutrition</code>, and the others follow the same rule.</p></blockquote><h2 id="stage-ids" tabindex="-1">Stage IDs <a class="header-anchor" href="#stage-ids" aria-label="Permalink to &quot;Stage IDs&quot;">​</a></h2><p>All seven stages declare <code>REQUIRED_ENTITY</code>, and non-player targets are skipped.</p><table tabindex="0"><thead><tr><th>Stage ID</th><th>Operation</th><th>Description</th></tr></thead><tbody><tr><td><code>cooking_add_nutrition</code></td><td>Add nutrition</td><td>Increases one nutrition type&#39;s current value.</td></tr><tr><td><code>cooking_remove_nutrition</code></td><td>Remove nutrition</td><td>Decreases one nutrition type&#39;s current value.</td></tr><tr><td><code>cooking_set_nutrition</code></td><td>Set nutrition</td><td>Sets one nutrition type&#39;s current value.</td></tr><tr><td><code>cooking_clear_nutrition</code></td><td>Clear nutrition</td><td>Sets one type, or every type, to its own <code>min</code>.</td></tr><tr><td><code>cooking_reset_nutrition</code></td><td>Reset nutrition</td><td>Sets one type, or every type, to its own <code>default</code>.</td></tr><tr><td><code>cooking_recheck_nutrition_threshold</code></td><td>Recheck thresholds</td><td>Re-evaluates the target&#39;s single and combination nutrition thresholds.</td></tr><tr><td><code>cooking_run_recipe_reward</code></td><td>Run recipe reward</td><td>Delivers one outcome branch of a loaded recipe through CookingRewardService.</td></tr></tbody></table><p>Which player is affected comes from the source, so there is no <code>target</code> parameter any more: use <code>self</code> for the caster, or <code>player_by_name</code> for a named player.</p><h2 id="adding-removing-and-setting-nutrition" tabindex="-1">Adding, removing, and setting nutrition <a class="header-anchor" href="#adding-removing-and-setting-nutrition" aria-label="Permalink to &quot;Adding, removing, and setting nutrition&quot;">​</a></h2><p><code>cooking_add_nutrition</code>, <code>cooking_remove_nutrition</code>, and <code>cooking_set_nutrition</code> share one parameter set.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>type</code></td><td>STRING</td><td>Yes</td><td>—</td><td>Nutrition type ID.</td></tr><tr><td><code>amount</code></td><td>EXPRESSION</td><td>Yes</td><td>—</td><td>Nutrition amount, may be a CoreLib expression.</td></tr></tbody></table><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | cooking_add_nutrition type=satiety amount=5&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | cooking_remove_nutrition type=hydration amount=3&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;player_by_name name=PlayerName | cooking_set_nutrition type=hydration amount=80&#39;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # amount as an expression</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | cooking_add_nutrition type=satiety amount=%var.base%*1.5&#39;</span></span></code></pre></div><p>On success the stage reports <code>type</code>, <code>old_value</code>, and <code>new_value</code>. A blank <code>type</code> fails at runtime with <code>INVALID_CONFIG</code>; when the nutrition service declines the operation, the stage fails with <code>REJECTED</code> and reports the reason.</p><h2 id="clearing-and-resetting-nutrition" tabindex="-1">Clearing and resetting nutrition <a class="header-anchor" href="#clearing-and-resetting-nutrition" aria-label="Permalink to &quot;Clearing and resetting nutrition&quot;">​</a></h2><p><code>cooking_clear_nutrition</code> sets values to each type&#39;s <code>min</code>; <code>cooking_reset_nutrition</code> sets them to each type&#39;s <code>default</code>. The difference is semantic: one starves the player, the other returns them to a neutral state.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>type</code></td><td>STRING</td><td>No</td><td><code>&quot;&quot;</code></td><td>Nutrition type ID. Empty covers every registered type.</td></tr></tbody></table><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | cooking_clear_nutrition type=hydration&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;player_by_name name=PlayerName | cooking_reset_nutrition&#39;</span></span></code></pre></div><p>An unregistered <code>type</code> fails with <code>INVALID_CONFIG</code>; having no registered types at all is skipped. The stage stops at the first type that fails, so it does not leave the nutrition record half-written.</p><h2 id="threshold-recheck" tabindex="-1">Threshold recheck <a class="header-anchor" href="#threshold-recheck" aria-label="Permalink to &quot;Threshold recheck&quot;">​</a></h2><p><code>cooking_recheck_nutrition_threshold</code> re-evaluates the target&#39;s nutrition thresholds. It has no parameters.</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | cooking_recheck_nutrition_threshold&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;player_by_name name=PlayerName | cooking_recheck_nutrition_threshold&#39;</span></span></code></pre></div><p>A disabled nutrition system or a player without a cached record is treated as skipped; neither is a fault.</p><h2 id="recipe-reward" tabindex="-1">Recipe reward <a class="header-anchor" href="#recipe-reward" aria-label="Permalink to &quot;Recipe reward&quot;">​</a></h2><p><code>cooking_run_recipe_reward</code> looks up a loaded recipe and delivers its outputs and outcome actions through CookingRewardService&#39;s single exit point. It does not build a recipe on the fly; <code>recipe</code> must already be loaded by the matching station loader.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>recipe</code></td><td>STRING</td><td>Yes</td><td>—</td><td>Recipe ID.</td></tr><tr><td><code>station</code></td><td>STRING</td><td>No</td><td><code>&quot;&quot;</code></td><td>Station folder name. Empty searches every station loader.</td></tr><tr><td><code>outcome</code></td><td>STRING</td><td>No</td><td><code>success</code></td><td>Outcome name or path, such as <code>success</code>, <code>perfect</code>, or <code>result.success</code>. A value without <code>.</code> is expanded to <code>result.&lt;name&gt;</code>.</td></tr><tr><td><code>drop_result</code></td><td>BOOLEAN</td><td>No</td><td><code>false</code></td><td>Drop outputs at the target instead of giving them.</td></tr><tr><td><code>include_outputs</code></td><td>BOOLEAN</td><td>No</td><td><code>true</code></td><td>Whether to deliver the outcome branch&#39;s <code>outputs</code>.</td></tr><tr><td><code>include_actions</code></td><td>BOOLEAN</td><td>No</td><td><code>true</code></td><td>Whether to execute the outcome branch&#39;s <code>actions</code>.</td></tr><tr><td><code>phase</code></td><td>STRING</td><td>No</td><td><code>&quot;&quot;</code></td><td>Phase name recorded for the nested actions. Empty generates <code>cooking.action.recipe.&lt;recipe id&gt;</code>.</td></tr></tbody></table><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;player_by_name name=PlayerName | cooking_run_recipe_reward recipe=apple_pie station=oven outcome=success&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | cooking_run_recipe_reward recipe=tea outcome=result.perfect drop_result=true include_actions=false&#39;</span></span></code></pre></div><p>A blank <code>recipe</code>, an unknown <code>station</code>, or a recipe that cannot be found all fail with <code>INVALID_CONFIG</code>. An outcome branch with neither <code>outputs</code> nor <code>actions</code> (or with both switches turned off) is skipped. On success the stage reports <code>recipe</code>, <code>station</code>, <code>outcome</code>, <code>outputs</code>, <code>actions</code>, and <code>target</code>.</p><p>The reward chain is asynchronous and fire-and-forget, so success from this stage means the delivery was submitted, not that it finished. The nested recipe actions run against a context this stage does not build, so the pipeline&#39;s declared-context checking does not extend into them.</p><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li><code>amount</code> is declared as EXPRESSION. Placeholders in the argument text are rendered before the expression is evaluated, so <code>%var.*%</code>, context placeholders written by the calling module, and PlaceholderAPI placeholders can all take part in the arithmetic.</li><li>When the nutrition service or the recipe reward service is not ready, the stage fails with <code>MISSING_CONTEXT</code> rather than skipping silently.</li><li>Placeholders visible to nested recipe actions include <code>recipe_id</code>, <code>recipe_name</code>, and <code>station_type</code>, plus the same names with a <code>cooking_</code> prefix and <code>cooking_outcome</code>.</li></ul>`,29)])])}const k=t(s,[["render",d]]);export{u as __pageData,k as default};
